\label{specs}
 ${\rm (i)}$ There exists a spectral sequence $(E^{p,
q}_r, d_r)$ derived from the filtration $\{K_n\}_{n\geq 0}$, where
$E_1^{p, q} = H^{p+q}_D(K_p/K_{p+1})$ and $d_1=j_1k_1$, and $E^{p,
q}_2=H_{d_1}(E^{p, q}_1)$ and $d_2=j_2k_2.$ The bidegree of $d_r$ is
$(r, 1-r)$.

${\rm (ii)}$ The spectral sequence $\{E^{p, q}_r, d_r\}$ converges
to the twisted de Rham cohomology
\begin{equation}
\begin{array}{lclc}
\bigoplus\limits_{ \rm{p+q =1 }}E^{p, q}_{\infty}\cong H^o(M, H)
\quad\mbox{and}\quad \bigoplus\limits_{ \rm{p+q= 0}}E^{p,
q}_{\infty}\cong H^e(M, H).
\end{array}
\end{equation}

\begin{enumerate}\item Note that
$$H_D^i(K_p)=\left\{\begin{array}{ll} H_D^e(K_p)&\mbox{$i$ is even,}\\
H_D^o(K_p)&\mbox{$i$ is odd.}
\end{array}
\right.$$ and $$
H_D^i(K_p/K_{p+1})=\left\{\begin{array}{ll} H_D^e(K_p/K_{p+1})&\mbox{$i$ is even,}\\
H_D^o(K_p/K_{p+1})&\mbox{$i$ is odd.}
\end{array}
\right.
$$
Then we have that $H_D^i(K_p)$ and $H_D^i(K_p/K_{p+1})$ are
$2$-periodic on $i$. Consequently, the spectral sequence
$\{E_r^{p,q}, d_r\}$ is $2$-periodic on $q$.

\item There is also a spectral sequence converging to the twisted
cohomology $H^*(M, E, H)$ for a flat vector bundle $E$ over $M$.
\end{enumerate}

\label{4.6}
$d_{2k}=0$ for $k\geq 1.$ Therefore, for $k\geq 1$,
 \begin{equation} \label{4.7}
E_{2k+1}^{p,q}=E_{2k}^{p,q}.
\end{equation}

\label{4.1}
For $[x_p]_{2t+3}\in E_{2t+3}^{p,q}$ $(t\geq1)$, there exist
$x_{p+2i}=x_{p+2i}^{(t)}$ $(1\leq i\leq t)$ such that $y_{p+2j+1}=0$
$(0\leq j\leq t)$ and
\begin{equation*}
d_{2t+3}[x_p]_{2t+3}=[\sum\limits_{i=1}^t
H_{2i+1}\wedge x_{p+2(t-i)+2}^{(t)}+H_{2t+3}\wedge x_p]_{2t+3},\\
\end{equation*}
where the $(p+2i)$-form $x_{p+2i}^{(t)}$ depends on $t$.

The theorem is shown by mathematical
induction on $t$.

When $t=1$, $[x_p]_{2t+3}=[x_p]_5$. $[x_p]_5\in E_5^{p,q}$ implies
that $dx_p=0$ and $d_3[x_p]=[H_3\wedge x_p]=0$ by
Proposition~\ref{e3}. Thus there exists a $(p+2)$-form $v_1$ such
that $H_3\wedge x_p=d(-v_1).$ We can choose $x_{p+2}^{(1)}=v_1$ to
get $y_{p+3}=dx_{p+2}^{(1)}+H_3\wedge x_p=dv_1+H_3\wedge x_p=0$ from
(\ref{6.7}). Note that
\begin{equation}\label{6.2}
\xymatrix{
&H_D^{p+q+1}(K_{p+1})&\ar[l]_{i_1^4} H_D^{p+q+1}(K_{p+5})\ar[r]^{j_1}&H_D^{p+q+1}(K_{p+5}/K_{p+6})\\
&[Dx]_D\ar[r]^{(i_1^{-1})^4}&[Dx]_D\ar[r]^{j_1}
& y_{p+5}, \\
}
\end{equation}
we obtain
\begin{equation}\label{6.3}
\begin{array}{ll}
d_5[x_p]_5&=j_5k_5[x_p]_5\\
&=j_5(k_1x_p)\\
&=j_5[Dx]_D\\

&=[j_1(i_1^{-1})^4[Dx]_D]_5\\

&=[y_{p+5}]_5.
\end{array}
\end{equation}
The reasons for the identities in (\ref{6.3}) are similar to those
of (\ref{3.12}). Thus we have
\begin{equation*}
\begin{array}{ll}
d_5[x_p]_5&=[dx_{p+4}+H_3\wedge x_{p+2}^{(1)}+H_5\wedge x_p]_5\\

&=[H_3\wedge x_{p+2}^{(1)}+H_5\wedge x_p]_5,
\end{array}
\end{equation*}
where the first identity follows from (\ref{6.3}) and the definition
of $y_{p+5}$ in (\ref{6.7}), and the second one follows from that
$dx_{p+4}$ vanishes in $E_5^{\ast,\ast}$. Hence the result holds for
$t=1$.

Suppose the result holds for $t\leq m-1$. Now we show that the
theorem also holds for $t=m$.

From $[x_p]_{2m+3}\in E_{2m+3}^{p,q}$, we have $[x_p]_{2m+1}\in
E_{2m+1}^{p,q}$ and $d_{2m+1}[x_p]_{2m+1}=0$. By induction, there
exist $x_{p+2i}^{(m-1)}$ ($1\leq i \leq m-1$) such that

\begin{equation}\label{4.8}
\left\{ \begin{array}{ll}&y^{(m-1)}_{p+1}(x_p)=dx_p=0,\\

&y^{(m-1)}_{p+3}(x_p) = dx_{p+2}^{(m-1)}+H_3\wedge x_p = 0,\\

&y^{(m-1)}_{p+2i+1}(x_p) =
dx_{p+2i}^{(m-1)}+\sum_{j=1}^{i-1}H_{2j+1}\wedge
x_{p+2(i-j)}^{(m-1)}+H_{2i+1}\wedge x_p\\

&\quad \quad \quad\quad\quad\ = 0~~ (2\leq i\leq m-1),\\

&d_{2m+1}[x_p]_{2m+1}=[\sum\limits_{i=1}^{m-1} H_{2i+1}\wedge
x_{p+2(m-i)}^{(m-1)}+H_{2m+1}\wedge x_p]_{2m+1}=0.
\end{array}\right.
\end{equation}

By $d_{2m}=0$ and the last equation in (\ref{4.8}), there exists a
$(p+2)$-form $w_{p+2}$ such that
\begin{equation}\label{4.3}
[\sum\limits_{i=1}^{m-1} H_{2i+1}\wedge
x_{p+2(m-i)}^{(m-1)}+H_{2m+1}\wedge
x_p]_{2m-1}=d_{2m-1}[w_{p+2}]_{2m-1}.
\end{equation}

By induction and $[w_{p+2}]_{2m-1}\in E_{2m-1}^{p+2,q-2}$, there
exist $w^{(m-2)}_{p+2(i+1)}$ $(1\leq i \leq m-2)$ such that

\begin{equation}\label{4.4}
\left\{ \begin{array}{ll}&y^{(m-2)}_{p+3}(w_{p+2})=dw_{p+2}=0,\\

&y^{(m-2)}_{p+5}(w_{p+2})=dw^{(m-2)}_{p+4}+H_3\wedge w_{p+2}=0,\\

&y^{(m-2)}_{p+2i+3}(w_{p+2}) =
dw^{(m-2)}_{p+2(i+1)}+\sum_{j=1}^{i-1}H_{2j+1}\wedge
w^{(m-2)}_{p+2(i-j+1)}+ H_{2i+1}\wedge w_{p+2}\\

 &\quad\quad\quad\quad\quad\quad\ \ = 0~~ (2\leq i\leq m-2),\\

&d_{2m-1}[w_{p+2}]_{2m-1}=[\sum\limits_{i=1}^{m-2} H_{2i+1}\wedge
w^{(m-2)}_{p+2(m-i)}+H_{2m-1}\wedge w_{p+2}]_{2m-1}.
\end{array}\right.
\end{equation}
By (\ref{4.3}) and the last equation in (\ref{4.4}), we obtain
$$[\sum\limits_{i=1}^{m-2} H_{2i+1}\wedge
(x_{p+2(m-i)}^{(m-1)}- w^{(m-2)}_{p+2(m-i)})+H_{2m-1}\wedge
(x_{p+2}^{(m-1)}-w_{p+2})+H_{2m+1}\wedge x_p]_{2m-1}=0.$$ Note that
$d_{2m-2}=0$, it follows that there exists a $(p+4)$-form $w_{p+4}$
such that
\begin{displaymath}
\begin{array}{ll}
 &[\sum\limits_{i=1}^{m-2} H_{2i+1}\wedge (x_{p+2(m-i)}^{(m-1)}-
w^{(m-2)}_{p+2(m-i)})+H_{2m-1}\wedge
(x_{p+2}^{(m-1)}-w_{p+2})+H_{2m+1}\wedge x_p]_{2m-3}\\

&=d_{2m-3}[w_{p+4}]_{2m-3}.
\end{array}
\end{displaymath}

Keeping the same iteration process as mentioned above, we have
\begin{equation*}
\begin{array}{ll}
&[\sum\limits_{i=1}^{2}(H_{2i+1}\wedge
(x_{p+2(m-i)}^{(m-1)}-\sum\limits_{j=1}^{m-3}w_{p+2(m-i)}^{(m-1-j)}))+\\

&\sum\limits_{i=3}^{m-1}(H_{2i+1}\wedge
(x_{p+2(m-i)}^{(m-1)}-\sum\limits_{j=1}^{
m-1-j}w_{p+2(m-i)}^{(m-1-j)}-w_{p+2(m-i)}))+H_{2m+1}\wedge x_p]_7=0.
\end{array}
\end{equation*}
By $d_6=0$, it follows that there exists a $(p+2(m-2))$-form
$w_{p+2(m-2)}$ such that
\begin{equation}\label{liu}
\begin{array}{ll}
&[\sum\limits_{i=1}^{2}(H_{2i+1}\wedge
(x_{p+2(m-i)}^{(m-1)}-\sum\limits_{j=1}^{m-3}w_{p+2(m-i)}^{(m-1-j)}))+
\sum\limits_{i=3}^{m-1}(H_{2i+1}\wedge
(x_{p+2(m-i)}^{(m-1)}-\\

&\sum\limits_{j=1}^{
m-i-1}w_{p+2(m-i)}^{(m-1-j)}-w_{p+2(m-i)}))+H_{2m+1}\wedge
x_p]_5=d_5[w_{p+2(m-2)}]_5.
\end{array}
\end{equation}

By induction and $[w_{p+2(m-2)}]_5\in E_5^{p+2(m-2),q-2(m-2)}$,
there exists  $w_{p+2(m-1)}^{(1)}$ such that
\begin{equation}\label{liu2}
\left\{\begin{array}{ll} &y_{p+2m-3}^{(1)}(w_{p+2(m-2)})=dw_{p+2(m-2)}=0,\\

&y_{p+2m-1}^{(1)}(w_{p+2(m-2)})=dw_{p+2(m-1)}^{(1)}+H_3\wedge w_{p+2(m-2)}=0,\\

&d_5[w_{p+2(m-2)}]_5=[H_3\wedge w_{p+2(m-1)}^{(1)}+H_5\wedge
w_{p+2(m-2)}]_5.
\end{array}\right.
\end{equation}
By (\ref{liu}), the last equation in (\ref{liu2}) and $d_4=0$, it
follows that there exists a $(p+2(m-1))$-form $w_{p+2(m-1)}$ such
that
\begin{equation*}
\begin{array}{ll}
&[(H_3\wedge
(x_{p+2(m-1)}^{(m-1)}-\sum\limits_{j=1}^{m-2}w_{p+2(m-1)}^{(m-1-j)}))+
\sum\limits_{i=2}^{m-1}(H_{2i+1}\wedge (x_{p+ 2(m-i)}^{(m-1)}-\\

&\sum\limits_{j=1}^{m-i-1}w_{p+2(m-i)}^{(m-1-j)}-w_{p+2(m-i)}))+H_{2m+1}\wedge
x_p]=d_3[w_{p+2(m-1)}]=[H_3\wedge w_{p+2(m-1)}]

\end{array}
\end{equation*}
and $y_{p+2m-1}^{(0)}(w_{p+2(m-1)})=dw_{p+2(m-1)}=0$. Thus there
exists a $(p+2m)$-form $w_{p+2m}$ such that
\begin{equation}\label{4.5}
\sum\limits_{i=1}^{m-1}(H_{2i+1}\wedge
(x_{p+2(m-i)}^{(m-1)}-\sum\limits_{j=1}^{m-i-1}w_{p+2(m-i)}^{(m-1-j)}-w_{p+2(m-i)}))+H_{2m+1}\wedge
x_p=dw_{p+2m}.
\end{equation}
By comparing (\ref{4.5}) with (\ref{6.7}), we choose at this time
\begin{equation}\label{liu3}
\left\{\begin{array}{ll} &x_{p+2}=x_{p+2}^{(m)}=x_{p+2}^{(m-1)}-w_{p+2},\\

&x_{p+2i}=x_{p+2i}^{(m)}=x_{p+2i}^{(m-1)}-\sum\limits_{j=1}^{i-1}w_{p+2i}^{(m-1-j)}-w_{p+2i}\quad
(2\leq i
\leq m-1),\\

&x_{p+2m}=x_{p+2m}^{(m)}=-w_{p+2m}.
\end{array}\right.
\end{equation}
From (\ref{6.7}), by a direct computation we have
\begin{equation}\label{liu4}
\left\{\begin{array}{ll} &y_{p+1}=y_{p+1}^{(m-1)}(x_p)=0,\\

&y_{p+2i-1}=y_{p+2i-1}^{(m-1)}(x_p)-\sum\limits_{j=1}^{i-1}y^{(m-1-j)}_{p+2i-1}(w_{p+2j})=0
\quad
(2\leq i \leq m),\\

&y_{p+2m+1}=0.
\end{array}\right.
\end{equation}
Note that
\begin{equation}\label{6.4}
\xymatrix{
&H_D^{p+q+1}(K_{p+1})&\ar[l]_{i_1^{2(m+1)}} H_D^{p+q+1}(K_{p+2m+3})\ar[r]^<<<<{j_1}&H_D^{p+q+1}(K_{p+2m+3}/K_{p+2m+4})\\
&[Dx]_D\ar[r]^{(i_1^{-1})^{2(m+1)}}&[Dx]_D\ar[r]^{j_1}
& y_{p+2m+3}. \\
}
\end{equation}
By the similar reasons as in (\ref{3.12}), the following identities
hold.
\begin{equation}\label{6.5}
\begin{array}{ll}
d_{2m+3}[x_p]_{2m+3}&=j_{2m+3}k_{2m+3}[x_p]_{2m+3}\\

&=j_{2m+3}(k_1x_p)\\

&=j_{2m+3}[Dx]_D\\

&=[j_1(i_1^{-1})^{2(m+1)}[Dx]_D]_{2m+3}\\

&=[y_{p+2m+3}]_{2m+3}.
\end{array}
\end{equation}
So we have
\begin{equation*}
\begin{array}{ll}
d_{2m+3}[x_p]_{2m+3}&=[y_{p+2m+3}]_{2m+3}\\

&=[dx_{p+2m+2}+\sum\limits_{i=1}^{m} H_{2i+1}\wedge
x_{p+2(m-i+1)}^{(m)}+H_{2m+3}\wedge x_p]_{2m+3} ~{\rm by ~(\ref{6.7}) }\\

&=[\sum\limits_{i=1}^{m} H_{2i+1}\wedge
x_{p+2(m-i+1)}^{(m)}+H_{2m+3}\wedge x_p]_{2m+3},
\end{array}
\end{equation*}
showing that the result also holds for $t=m$.

The proof of the theorem is finished.

\begin{enumerate}

\item

Theorems \ref{4.1} and \ref{4.2} show that the differentials in the
spectral sequence (\ref{ss}) can be computed in terms of cup
products with $H_{2i+1}$'s. The existence of $x_{p+2i}^{(t)}$'s and
$x_{p+2is}^{([\frac{t}{s}])}$'s in Theorems \ref{4.1} and \ref{4.2}
plays an essential role in proving Theorems \ref{differentials1} and
\ref{differentials2}, respectively. Theorems \ref{4.1} and \ref{4.2}
give a description of the differentials at the level of
$E_{2t+3}^{p,q}$ for the spectral sequence (\ref{ss}), which was
ignored in the previous studies of the twisted de Rham cohomology in
\cite{A-S, M-W}.

\item Note that Theorem \ref{4.2} is not a corollary of Theorem
\ref{4.1}, and it can not be obtained from Theorem \ref{4.1}
directly.

\end{enumerate}
